//! wasmCloud Component for Unified IR Pipeline UI API
//! 
//! REST API for the unified IR (Symbolic + Graph + Vector) pipeline UI

use wasmcloud_component::http;
use serde::{Deserialize, Serialize};
use std::io::Read;

// NOTE: wit_bindgen bindings are generated by wash build automatically
// The bindings are available through the wasmcloud::postgres module
// However, we need to explicitly generate them to use in our code
// For now, we'll use placeholder implementations until bindings are confirmed

mod handlers;
mod models;

use handlers::*;

struct Component;

http::export!(Component);

impl http::Server for Component {
    fn handle(
        request: http::IncomingRequest,
    ) -> http::Result<http::Response<String>> {
        let (parts, mut body) = request.into_parts();
        let path = parts.uri.path();
        
        // Read request body
        let mut body_buf = Vec::new();
        body.read_to_end(&mut body_buf).map_err(|_|
            http::ErrorCode::InternalError(Some("Failed to read request body".to_string()))
        )?;
        
        // Route requests
        match path {
            "/health" => Ok(http::Response::new("OK\n".to_string())),
            "/api/ir/entities" => {
                match parts.method.as_str() {
                    "GET" => handle_get_entities(),
                    "POST" => handle_create_entity(&body_buf),
                    _ => Ok(http::Response::new("Method Not Allowed\n".to_string())),
                }
            },
            path if path.starts_with("/api/ir/entities/") => {
                let id = path.strip_prefix("/api/ir/entities/").unwrap_or("");
                match parts.method.as_str() {
                    "GET" => handle_get_entity(id),
                    "PUT" => handle_update_entity(id, &body_buf),
                    "DELETE" => handle_delete_entity(id),
                    _ => Ok(http::Response::new("Method Not Allowed\n".to_string())),
                }
            },
            _ => Ok(http::Response::builder()
                .status(404)
                .body("Not Found\n".to_string())
                .unwrap()),
        }
    }
}

fn handle_get_entities() -> http::Result<http::Response<String>> {
    // TODO: Call postgres::query_entities() once wit_bindgen bindings are available
    let entities = handlers::postgres::query_entities()
        .map_err(|e| http::ErrorCode::InternalError(Some(e)))?;
    
    let json = serde_json::to_string(&entities)
        .map_err(|_| http::ErrorCode::InternalError(Some("Failed to serialize response".to_string())))?;
    
    // Use Response::new() with String
    Ok(http::Response::new(json))
}

fn handle_create_entity(body: &[u8]) -> http::Result<http::Response<String>> {
    let entity_data: serde_json::Value = serde_json::from_slice(body)
        .map_err(|_| http::ErrorCode::InternalError(Some("Invalid JSON".to_string())))?;
    
    let id = handlers::postgres::create_entity(&entity_data)
        .map_err(|e| http::ErrorCode::InternalError(Some(e)))?;
    
    let response = serde_json::json!({
        "id": id,
        "status": "created"
    });
    
    let json = serde_json::to_string(&response)
        .map_err(|_| http::ErrorCode::InternalError(Some("Failed to serialize response".to_string())))?;
    
    // Use Response::new() with String
    Ok(http::Response::new(json))
}

fn handle_get_entity(id: &str) -> http::Result<http::Response<String>> {
    let entity = handlers::postgres::get_entity(id)
        .map_err(|e| http::ErrorCode::InternalError(Some(e)))?;
    
    let json = serde_json::to_string(&entity)
        .map_err(|_| http::ErrorCode::InternalError(Some("Failed to serialize response".to_string())))?;
    
    // Use Response::new() with String
    Ok(http::Response::new(json))
}

fn handle_update_entity(id: &str, body: &[u8]) -> http::Result<http::Response<String>> {
    let entity_data: serde_json::Value = serde_json::from_slice(body)
        .map_err(|_| http::ErrorCode::InternalError(Some("Invalid JSON".to_string())))?;
    
    handlers::postgres::update_entity(id, &entity_data)
        .map_err(|e| http::ErrorCode::InternalError(Some(e)))?;
    
    let response = serde_json::json!({
        "id": id,
        "status": "updated"
    });
    
    let json = serde_json::to_string(&response)
        .map_err(|_| http::ErrorCode::InternalError(Some("Failed to serialize response".to_string())))?;
    
    // Use Response::new() with String
    Ok(http::Response::new(json))
}

fn handle_delete_entity(id: &str) -> http::Result<http::Response<String>> {
    handlers::postgres::delete_entity(id)
        .map_err(|e| http::ErrorCode::InternalError(Some(e)))?;
    
    let response = serde_json::json!({
        "id": id,
        "status": "deleted"
    });
    
    let json = serde_json::to_string(&response)
        .map_err(|_| http::ErrorCode::InternalError(Some("Failed to serialize response".to_string())))?;
    
    // Use Response::new() with String
    Ok(http::Response::new(json))
}

